/**
 * The icon for a file, matched like VS Code: exact name, then the longest dotted extension.
 * @param name File name without its folder
 * @param dark Whether the theme is dark; light themes get the light variant when one exists
 * @returns Path of the SVG under the Herdr app home, for `image()`
 */
export function fileIcon(name, dark = true) {
  const lower = name.toLowerCase();
  let icon = FILE_NAMES[lower];
  for (let i = lower.indexOf("."); !icon && i !== -1; i = lower.indexOf(".", i + 1)) icon = FILE_EXTENSIONS[lower.slice(i + 1)];
  if (!icon) return BASE + "default_file.svg";
  return BASE + (!dark && LIGHT_FILES.has(icon) ? `file_type_light_${icon}.svg` : `file_type_${icon}.svg`);
}

/**
 * The icon for a folder by its name.
 * @param name Folder name without its parent
 * @param open Whether the folder is expanded
 * @param dark Whether the theme is dark; light themes get the light variant when one exists
 * @returns Path of the SVG under the Herdr app home, for `image()`
 */
export function folderIcon(name, open = false, dark = true) {
  const icon = FOLDER_NAMES[name.toLowerCase()], suffix = open ? "_opened.svg" : ".svg";
  if (!icon) return BASE + "default_folder" + suffix;
  return BASE + (!dark && LIGHT_FOLDERS.has(icon) ? `folder_type_light_${icon}` : `folder_type_${icon}`) + suffix;
}
